using System.ComponentModel.DataAnnotations;
namespace SimplexLawFirm.Models;
public enum FeeDiscountStatus { Pending = 0, AutoApproved = 1, PendingDirectorReview = 2, DirectorApproved = 3, DirectorRejected = 4, CounterOffered = 5, CounterOfferAccepted = 6, CounterOfferRejected = 7, PendingDirector = PendingDirectorReview, AutomaticallyApproved = AutoApproved, Approved = DirectorApproved, Rejected = DirectorRejected, AcceptedCounterOffer = CounterOfferAccepted }
public static class PaymentReliability { public const string Good = "Good"; public const string Fair = "Fair"; public const string Poor = "Poor"; }
public sealed class FeeDiscountPolicy { public int Id { get; set; } [MaxLength(120)] public string MatterType { get; set; } = "General"; public decimal MinimumRecoveryPercent { get; set; } = 70; public decimal AutomaticApprovalPercent { get; set; } = 10; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; public int? UpdatedByUserId { get; set; } }
public sealed class FeeDiscountRequest { public int Id { get; set; } public int InvoiceId { get; set; } public Invoice Invoice { get; set; } = null!; public int ClientId { get; set; } public Client Client { get; set; } = null!; public decimal OriginalAmount { get; set; } public decimal ProposedAmount { get; set; } public decimal DiscountPercent { get; set; } [MaxLength(2000)] public string Reason { get; set; } = ""; public decimal MinimumRecoveryPercentSnapshot { get; set; } public decimal AutomaticApprovalPercentSnapshot { get; set; } public decimal EligibilityScore { get; set; } [MaxLength(20)] public string EligibilityTier { get; set; } = ""; public decimal EligibilityLimitSnapshot { get; set; } [MaxLength(300)] public string ThresholdCheckSnapshot { get; set; } = ""; [MaxLength(500)] public string? SupportingDocumentPath { get; set; } [MaxLength(40)] public string PaymentReliability { get; set; } = ""; [MaxLength(2000)] public string Recommendation { get; set; } = ""; public FeeDiscountStatus Status { get; set; } public decimal? CounterOfferAmount { get; set; } public int? DecidedByUserId { get; set; } [MaxLength(2000)] public string? DecisionReason { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime? DecidedAtUtc { get; set; } }
